import{_ as e,o as t,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Best UADK Acceleration Practice on Ceph Storage - Dai Zhiwei, Huawei","description":"","frontmatter":{"title":"Best UADK Acceleration Practice on Ceph Storage - Dai Zhiwei, Huawei","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","UADK","Storage Optimization","Security Acceleration","Blue Store"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Best_UADK_Acceleration_Practice_on_Ceph_Storage_-_Dai_Zhiwei_Huawei.md","filePath":"posts/2023/Best_UADK_Acceleration_Practice_on_Ceph_Storage_-_Dai_Zhiwei_Huawei.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Best_UADK_Acceleration_Practice_on_Ceph_Storage_-_Dai_Zhiwei_Huawei.md"};function a(n,i,s,_,p,c){return t(),l("div",null,[...i[0]||(i[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> UADK加速实践在安全存储中的应用</p><p><strong>主讲人：</strong> Julie（华为技术有限公司）</p><p><strong>会议内容总结：</strong></p><ol><li><p><strong>介绍与背景</strong></p><ul><li>Julie介绍了她在华为技术有限公司的工作背景，专注于安全数据处理已有五年。</li><li>本次演讲的主题是关于UADK（User Space Acceleration Development Kit）在安全存储中的加速实践。</li></ul></li><li><p><strong>数据处理结构概述</strong></p><ul><li>讨论了数据处理架构的概况，包括Ceph存储系统中的多种数据处理特性，如客户端加密、S3、HTTPS、RSW压缩、服务器端加密、MD5计算等。</li><li>强调了这些特性对系统性能的影响，特别是在Blue Store和RGW中的热点问题。</li></ul></li><li><p><strong>UADK解决方案</strong></p><ul><li>UADK是一个用户空间加速开发工具包，具有统一接口、高效、安全等优点。</li><li>UADK支持基于硬件的加密和压缩加速，无需CPU和HCC设备之间的内存复制。</li><li>UADK的安全性通过IOMMU限制设备和进程的访问权限来实现。</li></ul></li><li><p><strong>实践应用</strong></p><ul><li><strong>安全处理卸载：</strong> 展示了如何使用UADK引擎进行安全处理卸载，包括AES和MD5的硬件加速。</li><li><strong>数据压缩：</strong> 介绍了在数据压缩方面的实践，包括使用UADK进行Blue Store压缩和网络传输压缩。</li><li>展示了测试结果，表明使用UADK可以显著降低CPU使用率并提高性能。</li></ul></li><li><p><strong>其他优化工作</strong></p><ul><li>讨论了在安全处理方面的其他优化工作，如Lab RC优化和RGW对象加密与压缩的支持。</li><li>展示了这些优化带来的性能提升，如压缩速度的显著提高。</li></ul></li><li><p><strong>未来工作</strong></p><ul><li>提出了未来的工作方向，包括解决S380 DPS和Cifax安全模式中的热点问题。</li><li>计划将UADK支持集成到Ceph主分支中，包括UD corruption插件和UADK压缩加速器。</li><li>探讨了硬件加速的未来可能性，如减少内存访问频率的芯片模式加速。</li></ul></li></ol><p><strong>后续行动计划：</strong></p><ul><li>继续优化和扩展UADK在Ceph存储系统中的应用。</li><li>解决S380 DPS和Cifax安全模式中的性能瓶颈问题。</li><li>推动UADK支持的开放源代码工作，增强Ceph社区的参与和贡献。</li></ul><p><strong>结束语：</strong></p><ul><li>Julie感谢大家的参与，并期待未来在安全存储领域的进一步合作和创新。</li></ul><p><strong>会议时间：</strong> [具体时间] <strong>会议地点：</strong> [具体地点] <strong>参会人员：</strong> [参会人员名单]</p><p>以上是本次会议的详细纪要，涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</p>',11)])])}const D=e(r,[["render",a]]);export{u as __pageData,D as default};
